match names {
            [name] => format!("{message_start} {}?", MarkdownInlineCode(name.as_ref())),
            _ => {
                const CUTOFF_POINT: usize = 10;
                let mut listed_names = names
                    .iter()
                    .take(CUTOFF_POINT)
                    .map(|name| MarkdownInlineCode(name.as_ref()).to_string())
                    .collect::<Vec<_>>();
                let omitted_count = names.len().saturating_sub(CUTOFF_POINT);
                if omitted_count == 1 {
                    listed_names.push(".. 1 file not shown".into());
                } else if omitted_count > 1 {
                    listed_names.push(format!(".. {omitted_count} files not shown"));
                }

                format!(
                    "{message_start} the following {} files?\n{}",
                    names.len(),
                    listed_names.join("\n")
                )
            }
        }

match (trash, total_count) {
            (true, 1) => format!("Failed to trash {failed_count} of {total_count} file."),
            (true, _) => format!("Failed to trash {failed_count} of {total_count} files."),
            (false, 1) => format!("Failed to delete {failed_count} of {total_count} file."),
            (false, _) => format!("Failed to delete {failed_count} of {total_count} files."),
        }

match form.kind {
                    CompatibleProviderKind::OpenAi => {
                        "This provider will use an OpenAI-compatible API."
                    }
                    CompatibleProviderKind::Anthropic => {
                        "This provider will use an Anthropic Messages-compatible API."
                    }
                }

match section {
            Section::Staged => "No staged changes yet",
            Section::Unstaged => "No unstaged changes",
            _ => "No changes",
        }

match entry {
                                    Entry::NewUrl { url } => format!("Based off {url}"),
                                    Entry::NewRemoteName { url, .. } => {
                                        format!("Based off {url}")
                                    }
                                    Entry::NewBranch { .. } => {
                                        if let Some(current_branch) =
                                            self.repo.as_ref().and_then(|repo| {
                                                repo.read(cx).branch.as_ref().map(|b| b.name())
                                            })
                                        {
                                            format!("Based off {}", current_branch)
                                        } else {
                                            "Based off the current branch".to_string()
                                        }
                                    }
                                    Entry::Branch { .. } => String::new(),
                                }

if let Some(offset) = self.relative_line_from_query(cx) {
            let target_line = if offset >= 0 {
                self.current_line.saturating_add(offset as u32)
            } else {
                self.current_line.saturating_sub(offset.unsigned_abs())
            };
            format!("Go to line {target_line} ({offset:+} from current)").into()
        } else {
            match self.line_and_char_from_query(cx) {
                Some((line, Some(character))) => {
                    format!("Go to line {line}, character {character}").into()
                }
                Some((line, None)) => format!("Go to line {line}").into(),
                None => self.current_text.clone(),
            }
        }

if is_edit {
        "Configure MCP Server"
    } else {
        match transport {
            McpTransport::Stdio => "Add Local MCP Server",
            McpTransport::Http => "Add Remote MCP Server",
        }
    }

if self.primary_changes_action_stages() {
            ("Stage All", StageAll.boxed_clone(), true, "git add --all")
        } else {
            ("Unstage All", UnstageAll.boxed_clone(), false, "git reset")
        }

if self.commit_editor_expanded {
                    (IconName::Minimize, "Collapse Commit Editor")
                } else {
                    (IconName::Maximize, "Expand Commit Editor")
                }

if is_unpushed {
                                                    SharedString::from(format!(
                                                        "Contains Unpushed Changes — {}",
                                                        short_sha.clone(),
                                                    ))
                                                } else {
                                                    short_sha.clone()
                                                }

